import * as vscode from "vscode"

import {
  EVENT_NAME,
  POINTER_COMMAND_NAME,
  WORKSPACE_STORAGE_KEY
} from "../../common/constants"
import { logger } from "../../common/logger"
import {
  ContextValue,
  NewDocumentRequest
} from "../../common/messaging/protocol"
import { AnyContextItem } from "../../common/types"
import { Agent } from "../agent"
import { searchSymbols } from "../chat/symbols"
import { ExtensionBridge } from "../messaging/bridge"
import { SessionManager } from "../session-manager"
import { getLanguage, getTerminal, getTextSelection, getTheme } from "../utils"

import { resolveLanguageId, stripShellPrompts } from "./code-actions"
import { FileHandler } from "./file-handler"
import { FileTreeProvider } from "./file-tree"

const storageKeyFor = (scope: string, key: string) => `${scope}-${key}`

export class BaseProvider {
  private _fileTreeProvider: FileTreeProvider
  private _sessionManager: SessionManager | undefined
  private _disposables: vscode.Disposable[] = []
  public bridge: ExtensionBridge | undefined
  public agent: Agent | undefined
  public createAgent?: (bridge: ExtensionBridge) => Agent
  public context: vscode.ExtensionContext
  public webView?: vscode.Webview

  private _sidebarReadyHandler?: () => void

  public registerSidebarReadyHandler(handler: () => void) {
    this._sidebarReadyHandler = handler
  }

  constructor(
    context: vscode.ExtensionContext,
    sessionManager?: SessionManager
  ) {
    this.context = context
    this._fileTreeProvider = new FileTreeProvider()
    this._sessionManager = sessionManager
  }

  public registerWebView(webView: vscode.Webview) {
    this.dispose()
    this.webView = webView
    this.bridge = new ExtensionBridge(webView)
    new FileHandler(this.bridge)
    this.agent = this.createAgent?.(this.bridge)
    this.registerHandlers(this.bridge)
    this.registerEditorListeners(this.bridge)
    logger.info("Webview registered successfully")
  }

  public dispose() {
    this.agent?.abort()
    this.agent = undefined
    this.bridge?.dispose()
    this.bridge = undefined
    this._disposables.forEach((disposable) => disposable.dispose())
    this._disposables = []
  }

  private registerHandlers(bridge: ExtensionBridge) {
    bridge.handleAll({
      [EVENT_NAME.pointerAcceptSolution]: (code) =>
        void vscode.commands.executeCommand(POINTER_COMMAND_NAME.applyCode, code),
      [EVENT_NAME.pointerChatMessage]: ({ messages, mentions }) =>
        void this.agent?.completion(messages, mentions),
      [EVENT_NAME.pointerFileListRequest]: () =>
        this._fileTreeProvider.getAllFiles(),
      [EVENT_NAME.pointerGetConfigValue]: ({ key }) => ({
        key,
        value: vscode.workspace.getConfiguration("pointer").get(key)
      }),
      [EVENT_NAME.pointerGetContextItems]: () =>
        this.broadcastContextItems(this.readContextItems()),
      [EVENT_NAME.pointerGlobalContext]: ({ key }) =>
        this.readGlobalContext(key),
      [EVENT_NAME.pointerGetWorkspaceContext]: ({ key }) =>
        this.readWorkspaceContext(key),
      [EVENT_NAME.pointerSessionContext]: ({ key }) =>
        this.readSessionContext(key),
      [EVENT_NAME.pointerSetGlobalContext]: (value) =>
        this.writeGlobalContext(value),
      [EVENT_NAME.pointerSetWorkspaceContext]: (value) =>
        this.writeWorkspaceContext(value),
      [EVENT_NAME.pointerSetSessionContext]: (value) =>
        this.writeSessionContext(value),
      [EVENT_NAME.pointerNewConversation]: () => this.newConversation(),
      [EVENT_NAME.pointerNewDocument]: (request) =>
        this.createNewUntitledDocument(request),
      [EVENT_NAME.pointerRemoveContextItem]: (id) => this.removeContextItem(id),
      [EVENT_NAME.pointerRunInTerminal]: (command) =>
        this.sendToTerminal(command),
      [EVENT_NAME.pointerInsertAtCursor]: (code) => this.insertAtCursor(code),
      [EVENT_NAME.pointerSendTheme]: () => getTheme(),
      [EVENT_NAME.pointerSetConfigValue]: ({ key, value }) =>
        void vscode.workspace
          .getConfiguration("pointer")
          .update(key, value, vscode.ConfigurationTarget.Global),
      [EVENT_NAME.pointerSidebarReady]: () => this._sidebarReadyHandler?.(),
      [EVENT_NAME.pointerStopGeneration]: () => this.destroyStream(),
      [EVENT_NAME.pointerToolApproval]: ({ id, run, always }) => this.agent?.answerToolApproval(id, run, always),
      [EVENT_NAME.pointerToolStop]: ({ id }) => this.agent?.stopToolStep(id),
      [EVENT_NAME.pointerSymbolSearch]: ({ query }) => searchSymbols(query),
      [EVENT_NAME.pointerTextSelection]: () => getTextSelection()
    })
  }

  private registerEditorListeners(bridge: ExtensionBridge) {
    this._disposables.push(
      vscode.window.onDidChangeActiveColorTheme(() => {
        bridge.emit(EVENT_NAME.pointerSendTheme, getTheme())
      }),
      vscode.window.onDidChangeTextEditorSelection((event) => {
        bridge.emit(
          EVENT_NAME.pointerTextSelection,
          event.textEditor.document.getText(event.selections[0])
        )
      })
    )
  }

  public destroyStream = () => {
    this.agent?.abort()
    this.bridge?.emit(EVENT_NAME.pointerStopGeneration)
  }

  private readContextItems = () =>
    this.context?.workspaceState.get<AnyContextItem[]>(
      WORKSPACE_STORAGE_KEY.contextItems
    ) || []

  addContextItem = (item: AnyContextItem) => {
    const items = this.readContextItems()
    const index = items.findIndex((existing) => existing.id === item.id)
    const updated = [...items]
    if (index > -1) updated[index] = item
    else updated.push(item)
    this.saveContextItems(updated)
  }

  removeContextItem = (id: string) => {
    this.saveContextItems(this.readContextItems().filter((i) => i.id !== id))
  }

  private saveContextItems = (items: AnyContextItem[]) => {
    this.context?.workspaceState.update(
      WORKSPACE_STORAGE_KEY.contextItems,
      items
    )
    this.broadcastContextItems(items)
  }

  private broadcastContextItems = (items: AnyContextItem[]) => {
    this.bridge?.emit(EVENT_NAME.pointerUpdateContextItems, items)
  }

  private readGlobalContext = (key: string): ContextValue => ({
    key,
    value: this.context?.globalState.get(
      storageKeyFor(EVENT_NAME.pointerGlobalContext, key)
    )
  })

  private writeGlobalContext = ({ key, value }: ContextValue) => {
    this.context?.globalState.update(
      storageKeyFor(EVENT_NAME.pointerGlobalContext, key),
      value
    )
    this.bridge?.emit(EVENT_NAME.pointerGlobalContext, { key, value })
  }

  private readWorkspaceContext = (key: string): ContextValue => ({
    key,
    value: this.context?.workspaceState.get(
      storageKeyFor(EVENT_NAME.pointerGetWorkspaceContext, key)
    )
  })

  private writeWorkspaceContext = ({ key, value }: ContextValue) => {
    this.context?.workspaceState.update(
      storageKeyFor(EVENT_NAME.pointerGetWorkspaceContext, key),
      value
    )
    this.bridge?.emit(EVENT_NAME.pointerGetWorkspaceContext, { key, value })
  }

  private readSessionContext = (key: string): ContextValue => ({
    key,
    value: this._sessionManager?.get(key)
  })

  private writeSessionContext = ({ key, value }: ContextValue) => {
    this._sessionManager?.set(key, value)
    this.bridge?.emit(EVENT_NAME.pointerSessionContext, { key, value })
  }

  public newConversation = () => {
    this.agent?.resetConversation()
    this.bridge?.emit(EVENT_NAME.pointerNewConversation)
    this.agent?.discardReply()
  }

  private createNewUntitledDocument = async ({
    content,
    language
  }: NewDocumentRequest) => {
    const document = await vscode.workspace.openTextDocument({
      content,
      language: await resolveLanguageId(language, getLanguage().languageId)
    })
    await vscode.window.showTextDocument(document)
  }

  private insertAtCursor = async (code: string) => {
    const editor = vscode.window.activeTextEditor
    if (!editor) {
      void vscode.window.showWarningMessage(
        "Open a file to insert the code into."
      )
      return
    }
    await vscode.window.showTextDocument(editor.document, editor.viewColumn)
    await editor.edit((builder) => {
      for (const selection of editor.selections) builder.replace(selection, code)
    })
  }

  private sendToTerminal = async (command: string) => {
    const terminal = await getTerminal()
    if (!terminal) return
    terminal.show()
    terminal.sendText(stripShellPrompts(command), false)
  }
}

import React, { useState } from "react"
import { Code } from "@pointersh/highlight/react"

import { EVENT_NAME } from "../common/constants"
import { ToolStepView } from "../common/types"

import { emit } from "./messaging"
import { useTranslation } from "./strings"
import { ToolOutput } from "./tool-output"
import { cx } from "./utils"

import styles from "./styles/tool-steps.module.css"

const STATUS_ICON: Record<ToolStepView["status"], string> = {
  running: "codicon-loading codicon-modifier-spin",
  waiting: "codicon-terminal",
  done: "codicon-check",
  failed: "codicon-error",
  skipped: "codicon-circle-slash",
  stopped: "codicon-debug-stop"
}

const LIVE_LINES = 8

const lastLines = (text: string, count: number) => text.trimEnd().split("\n").slice(-count).join("\n")

const Summary = ({ text }: { text: string }) => (
  <>
    {text.split(/(`[^`]+`)/).map((part, i) =>
      part.startsWith("`") && part.endsWith("`") && part.length > 1 ? (
        <code key={i}>{part.slice(1, -1)}</code>
      ) : (
        <React.Fragment key={i}>{part}</React.Fragment>
      )
    )}
  </>
)

export const answerToolStep = (step: ToolStepView, how: "run" | "always" | "skip") =>
  emit(EVENT_NAME.pointerToolApproval, {
    id: step.id,
    run: how !== "skip",
    ...(how === "always" && step.approval !== "change" && !step.noAlways ? { always: true } : {})
  })

const Step = ({ step }: { step: ToolStepView }) => {
  const { t } = useTranslation()
  const waiting = step.status === "waiting"
  const [open, setOpen] = useState(false)
  const inspectable = !!step.output || !!Object.keys(step.args ?? {}).length
  const live = step.status === "running" && step.name === "run_command" && !!step.output?.trim()
  const finishedCommand =
    step.name === "run_command" && step.status !== "running" && step.status !== "waiting" ? step.args?.command?.trim() : undefined
  const [copied, setCopied] = useState(false)

  return (
    <li className={cx(styles.step, styles[step.status])}>
      <div className={styles.head}>
        <button
          type="button"
          className={styles.row}
          onClick={() => setOpen((prev) => !prev)}
          disabled={!inspectable || waiting}
          aria-expanded={open}
        >
          <span className={styles.glyph} aria-hidden="true">
            <span
              className={cx("codicon", waiting && step.approval === "change" ? "codicon-question" : STATUS_ICON[step.status])}
            />
          </span>
          <span className={styles.summary}>
            <Summary text={step.summary} />
          </span>
          {inspectable && !waiting && (
            <span
              className={cx("codicon", open ? "codicon-chevron-up" : "codicon-chevron-down", styles.chevron)}
              aria-hidden="true"
            />
          )}
        </button>
        {finishedCommand && (
          <>
            <button
              type="button"
              className={styles.stop}
              onClick={() => {
                void navigator.clipboard.writeText(finishedCommand).then(() => setCopied(true))
              }}
              title={t(copied ? "copied-to-clipboard" : "tool-copy-command")}
              aria-label={t("tool-copy-command")}
            >
              <span className={cx("codicon", copied ? "codicon-check" : "codicon-copy")} aria-hidden="true" />
            </button>
            <button
              type="button"
              className={styles.stop}
              onClick={() => emit(EVENT_NAME.pointerRunInTerminal, finishedCommand)}
              title={t("tool-command-to-terminal-title")}
              aria-label={t("tool-command-to-terminal")}
            >
              <span className="codicon codicon-terminal" aria-hidden="true" />
            </button>
          </>
        )}
        {step.stoppable && step.status === "running" && (
          <button
            type="button"
            className={styles.stop}
            onClick={() => emit(EVENT_NAME.pointerToolStop, { id: step.id })}
            title={t("tool-stop-title")}
            aria-label={t("tool-stop")}
          >
            <span className="codicon codicon-debug-stop" aria-hidden="true" />
          </button>
        )}
      </div>
      {waiting && (
        <div className={styles.approval}>
          <div className={styles.approvalLabel}>
            {t(step.approval === "change" ? "tool-change-waiting" : step.mcpTool ? "tool-mcp-waiting" : "tool-command-waiting")}
          </div>
          <div className={styles.command}>
            {step.approval === "change" || step.mcpTool ? (
              <pre className={styles.output}>{step.command}</pre>
            ) : (
              <Code code={step.command ?? ""} language="bash" />
            )}
          </div>
          <div className={styles.actions}>
            <button type="button" className={styles.run} onClick={() => answerToolStep(step, "run")}>
              <span className={cx("codicon", step.approval === "change" ? "codicon-check" : "codicon-play")} aria-hidden="true" />
              {t(step.approval === "change" ? "tool-apply" : "tool-run")}
            </button>
            {step.approval !== "change" && !step.noAlways && (
              <button
                type="button"
                className={styles.skip}
                title={t(step.mcpTool ? "tool-always-run-mcp-title" : "tool-always-run-title", { tool: step.mcpTool })}
                onClick={() => answerToolStep(step, "always")}
              >
                {t("tool-always-run")}
              </button>
            )}
            <button type="button" className={styles.skip} onClick={() => answerToolStep(step, "skip")}>
              {t("tool-skip")}
            </button>
          </div>
          <div className={styles.keys}>
            {t(step.approval === "change" ? "tool-change-keys" : step.noAlways ? "tool-command-keys-ask" : "tool-command-keys")}
          </div>
        </div>
      )}
      {live && !open && <pre className={styles.live}>{lastLines(step.output!, LIVE_LINES)}</pre>}
      {open && !waiting && (
        <div className={styles.detail}>
          <ToolOutput step={step} />
        </div>
      )}
    </li>
  )
}

const Said = ({ step }: { step: ToolStepView }) => {
  const { t } = useTranslation()
  return (
    <li className={styles.said}>
      <span className={styles.saidWho}>{t("tool-said")}</span>
      <span className={styles.saidText}>{step.summary}</span>
    </li>
  )
}

export const ToolSteps = ({ steps }: { steps?: ToolStepView[] }) => {
  if (!steps?.length) return null
  return (
    <ol className={styles.panel}>
      {steps.map((step) =>
        step.said ? <Said key={step.id} step={step} /> : <Step key={step.id} step={step} />
      )}
    </ol>
  )
}

export default ToolSteps

import json, math, os, re, sys, time
root = sys.argv[1]; qs = json.load(open(os.path.join(os.path.dirname(__file__), "queries.json")))
STOP = set("a an the and or of to in for with is are be by on at as it this that from where how what which".split())
EXT = re.compile(r"\.(py|rst|md|txt|toml|cfg|html)$")
def tok(s): return [t for t in re.split(r"[^a-z0-9]+", re.sub(r"([a-z])([A-Z])", r"\1 \2", s).lower()) if t and t not in STOP]
t0 = time.perf_counter(); docs = []
for d, ds, fs in os.walk(root):
    ds[:] = [x for x in ds if not x.startswith(".")]
    for f in fs:
        if not EXT.search(f) or f.startswith("."): continue
        p = os.path.join(d, f); rel = os.path.relpath(p, root); lines = open(p, encoding="utf8", errors="ignore").read().split("\n")
        for i in range(0, len(lines), 40):
            t = tok(rel + " " + "\n".join(lines[i:i+40])); tf = {}
            for w in t: tf[w] = tf.get(w, 0) + 1
            docs.append((rel, len(t), tf))
df = {}
for _, _, tf in docs:
    for w in tf: df[w] = df.get(w, 0) + 1
N = len(docs); avg = sum(d[1] for d in docs) / N
index = (time.perf_counter() - t0) * 1000; out = []
for q in qs:
    s = time.perf_counter(); terms = tok(q["q"]); scored = []
    for rel, n, tf in docs:
        sc = 0.0
        for w in terms:
            f = tf.get(w)
            if f: sc += math.log(1 + (N - df[w] + .5) / (df[w] + .5)) * f * 2.2 / (f + 1.2 * (.25 + .75 * n / avg))
        if sc > 0: scored.append((sc, rel))
    scored.sort(reverse=True); seen = []
    for _, r in scored:
        if r not in seen: seen.append(r)
    out.append({"ms": (time.perf_counter() - s) * 1000, "files": seen})
print(json.dumps({"index": index, "out": out}))

mod index;
mod parse;
#[cfg(feature = "semantic")]
mod semantic;

use index::{FileData, Index};
use rayon::prelude::*;
use rmcp::handler::server::wrapper::Parameters;
use rmcp::schemars::JsonSchema;
use rmcp::transport::streamable_http_server::{
    session::local::LocalSessionManager, StreamableHttpServerConfig, StreamableHttpService,
};
use rmcp::{tool, tool_router};
use serde::Deserialize;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, RwLock};
use std::time::{Duration, Instant};

const MAX_FILE_BYTES: u64 = 1_000_000;
const LOCKFILES: &[&str] = &[
    "package-lock.json",
    "yarn.lock",
    "pnpm-lock.yaml",
    "Cargo.lock",
    "poetry.lock",
    "uv.lock",
    "go.sum",
    "composer.lock",
    "Gemfile.lock",
];

struct Store {
    root: PathBuf,
    files: Mutex<HashMap<String, FileData>>,
    index: RwLock<Arc<Index>>,
}

impl Store {
    fn relative(&self, path: &Path) -> Option<String> {
        path.strip_prefix(&self.root)
            .ok()
            .map(|p| p.to_string_lossy().replace('\\', "/"))
    }

    fn read(&self, path: &Path) -> Option<(String, FileData)> {
        let rel = self.relative(path)?;
        let name = path.file_name()?.to_string_lossy();
        if LOCKFILES.contains(&name.as_ref())
            || rel.split('/').any(|p| p == ".git" || p == ".pointer")
        {
            return None;
        }
        let meta = std::fs::metadata(path).ok()?;
        if !meta.is_file() || meta.len() > MAX_FILE_BYTES {
            return None;
        }
        let bytes = std::fs::read(path).ok()?;
        if bytes.iter().take(8192).any(|&b| b == 0) {
            return None;
        }
        let src = String::from_utf8(bytes).ok()?;
        let hash = xxhash_rust::xxh3::xxh3_64(src.as_bytes());
        let parsed = parse::parse(&rel, &src);
        Some((rel, FileData { hash, parsed }))
    }

    fn index_all(&self) {
        let paths: Vec<PathBuf> = ignore::WalkBuilder::new(&self.root)
            .hidden(true)
            .build()
            .filter_map(Result::ok)
            .filter(|e| e.file_type().is_some_and(|t| t.is_file()))
            .map(|e| e.into_path())
            .collect();
        let files: HashMap<String, FileData> =
            paths.par_iter().filter_map(|p| self.read(p)).collect();
        *self.files.lock().unwrap() = files;
        self.rebuild();
    }

    fn update(&self, changed: &[PathBuf], ignored: &ignore::gitignore::Gitignore) {
        let mut dirty = false;
        {
            let mut files = self.files.lock().unwrap();
            for path in changed {
                let Some(rel) = self.relative(path) else {
                    continue;
                };
                if ignored
                    .matched_path_or_any_parents(path, path.is_dir())
                    .is_ignore()
                {
                    continue;
                }
                match self.read(path) {
                    Some((rel, data)) => {
                        if files.get(&rel).map(|f| f.hash) != Some(data.hash) {
                            files.insert(rel, data);
                            dirty = true;
                        }
                    }
                    None => dirty |= files.remove(&rel).is_some(),
                }
            }
        }
        if dirty {
            self.rebuild();
        }
    }

    fn rebuild(&self) {
        let index = Index::build(&self.files.lock().unwrap());
        *self.index.write().unwrap() = Arc::new(index);
    }

    fn current(&self) -> Arc<Index> {
        self.index.read().unwrap().clone()
    }
}

#[derive(Deserialize, JsonSchema)]
struct SearchArgs {
    query: String,
    budget_tokens: Option<usize>,
}

#[derive(Deserialize, JsonSchema)]
struct SymbolArgs {
    name: String,
}

#[derive(Deserialize, JsonSchema)]
struct MapArgs {
    budget_tokens: Option<usize>,
}

#[derive(Clone)]
struct Retrieval {
    store: Arc<Store>,
    #[cfg(feature = "semantic")]
    semantic: Option<Arc<semantic::Semantic>>,
}

impl Retrieval {
    #[cfg(feature = "semantic")]
    fn semantic_signal(&self, index: &Index, query: &str) -> Vec<(usize, f32, String)> {
        self.semantic
            .as_ref()
            .map(|s| s.rank(index, query))
            .unwrap_or_default()
    }

    #[cfg(not(feature = "semantic"))]
    fn semantic_signal(&self, _: &Index, _: &str) -> Vec<(usize, f32, String)> {
        Vec::new()
    }

    #[cfg(feature = "semantic")]
    fn semantic_status(&self) -> String {
        self.semantic.as_ref().map_or_else(
            || "semantic: off".into(),
            |s| format!("{}; vectors {} KB", s.status(), s.memory_bytes() / 1024),
        )
    }

    #[cfg(not(feature = "semantic"))]
    fn semantic_status(&self) -> String {
        "semantic: off (built without the semantic feature)".into()
    }
}

#[tool_router(server_handler)]
impl Retrieval {
    #[tool(
        description = "Find the code most relevant to a question or task, packed within a token budget. Lists the chosen chunks with a computed reason for each, then their contents.",
        annotations(read_only_hint = true)
    )]
    fn search_codebase(&self, Parameters(args): Parameters<SearchArgs>) -> String {
        let started = Instant::now();
        let index = self.store.current();
        let semantic = index::Precomputed(self.semantic_signal(&index, &args.query));
        let extra: Vec<&dyn index::Signal> = if semantic.0.is_empty() {
            Vec::new()
        } else {
            vec![&semantic]
        };
        let out = index.search_text(
            &args.query,
            args.budget_tokens.unwrap_or(4500).min(5000),
            &extra,
        );
        eprintln!(
            "pointer-retrieval: search {:?} in {:?}",
            args.query,
            started.elapsed()
        );
        out
    }

    #[tool(
        description = "Where a symbol is defined and where it is referenced (path:line).",
        annotations(read_only_hint = true)
    )]
    fn find_symbol(&self, Parameters(args): Parameters<SymbolArgs>) -> String {
        self.store.current().find_symbol(&args.name)
    }

    #[tool(
        description = "A map of the most important files and their key definitions, ranked by PageRank over references, fitted to a token budget.",
        annotations(read_only_hint = true)
    )]
    fn repo_map(&self, Parameters(args): Parameters<MapArgs>) -> String {
        self.store
            .current()
            .repo_map(args.budget_tokens.unwrap_or(2000))
    }

    #[tool(
        description = "Indexing state: chunk count and whether semantic search is off, building (with progress) or ready.",
        annotations(read_only_hint = true)
    )]
    fn index_status(&self) -> String {
        let index = self.store.current();
        format!(
            "{}\nchunks: {} in {} files",
            self.semantic_status(),
            index.chunks.len(),
            index.files
        )
    }
}

fn watch(
    store: Arc<Store>,
    after: impl Fn() + Send + 'static,
) -> notify::Result<notify::RecommendedWatcher> {
    use notify::Watcher;
    let (tx, rx) = std::sync::mpsc::channel::<PathBuf>();
    let mut watcher = notify::recommended_watcher(move |event: notify::Result<notify::Event>| {
        if let Ok(event) = event {
            for path in event
                .paths
                .into_iter()
                .filter(|p| !p.components().any(|c| c.as_os_str() == ".pointer"))
            {
                let _ = tx.send(path);
            }
        }
    })?;
    watcher.watch(&store.root, notify::RecursiveMode::Recursive)?;
    let (ignored, _) = ignore::gitignore::Gitignore::new(store.root.join(".gitignore"));
    std::thread::spawn(move || {
        while let Ok(first) = rx.recv() {
            let mut batch = vec![first];
            while let Ok(path) = rx.recv_timeout(Duration::from_millis(300)) {
                batch.push(path);
            }
            batch.sort();
            batch.dedup();
            let started = Instant::now();
            store.update(&batch, &ignored);
            after();
            eprintln!(
                "pointer-retrieval: reindexed {} paths in {:?}",
                batch.len(),
                started.elapsed()
            );
        }
    });
    Ok(watcher)
}

fn arg(args: &[String], name: &str) -> Option<String> {
    args.iter()
        .position(|a| a == name)
        .and_then(|i| args.get(i + 1).cloned())
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let root = PathBuf::from(arg(&args, "--root").ok_or_else(|| {
        anyhow::anyhow!("usage: pointer-retrieval --root <dir> [--port 0] [--semantic]")
    })?);
    let root = root.canonicalize()?;
    let port: u16 = arg(&args, "--port")
        .map(|p| p.parse())
        .transpose()?
        .unwrap_or(0);

    let store = Arc::new(Store {
        root,
        files: Mutex::new(HashMap::new()),
        index: RwLock::new(Arc::new(Index::build(&HashMap::new()))),
    });
    let started = Instant::now();
    store.index_all();
    let index = store.current();
    eprintln!(
        "pointer-retrieval: indexed {} files, {} chunks in {:?}",
        index.files,
        index.chunks.len(),
        started.elapsed()
    );
    #[cfg(feature = "semantic")]
    let semantic = args.iter().any(|a| a == "--semantic").then(|| {
        let source = store.clone();
        semantic::Semantic::start(&store.root, move || source.current())
    });
    #[cfg(not(feature = "semantic"))]
    if args.iter().any(|a| a == "--semantic") {
        eprintln!("pointer-retrieval: built without the semantic feature; --semantic ignored");
    }
    #[cfg(feature = "semantic")]
    let notify = semantic.clone();
    let _watcher = watch(store.clone(), move || {
        #[cfg(feature = "semantic")]
        if let Some(s) = &notify {
            s.changed();
        }
    })?;

    let token = uuid::Uuid::new_v4().simple().to_string();
    let mut config = StreamableHttpServerConfig::default();
    config.legacy_session_mode = false;
    config.json_response = true;
    let service_store = store.clone();
    let service = StreamableHttpService::new(
        move || {
            Ok(Retrieval {
                store: service_store.clone(),
                #[cfg(feature = "semantic")]
                semantic: semantic.clone(),
            })
        },
        Arc::new(LocalSessionManager::default()),
        config,
    );
    let expected = format!("Bearer {token}");
    let app = axum::Router::new()
        .nest_service("/mcp", service)
        .layer(axum::middleware::from_fn(
            move |req: axum::extract::Request, next: axum::middleware::Next| {
                let ok = req
                    .headers()
                    .get("authorization")
                    .and_then(|v| v.to_str().ok())
                    == Some(expected.as_str());
                async move {
                    if ok {
                        next.run(req).await
                    } else {
                        axum::http::StatusCode::UNAUTHORIZED.into_response()
                    }
                }
            },
        ));
    let listener = tokio::net::TcpListener::bind(("127.0.0.1", port)).await?;
    let addr = listener.local_addr()?;
    println!("READY http://127.0.0.1:{}/mcp {token}", addr.port());
    axum::serve(listener, app).await?;
    Ok(())
}

